class FEMenuEntry
{
public:
	int entry_num;
	FEMenuEntry *next;
	FEMenuEntry *previous;
	char pad0[0x44];
	FEMenuEntry *up;
	FEMenuEntry *down;
	FEMenuEntry *left;
	FEMenuEntry *right;
	virtual ~FEMenuEntry();
	virtual void Load();
	virtual void OnSelect();
	virtual void Highlight(bool highlighted = true, bool animate = true);
	virtual void Disable(bool disabled = true);
	virtual bool GetDisable();
};

class SoundScriptManager
{
public:
	enum EventType { SS_FE_UPDOWN = 25 };
	static inline SoundScriptManager *inst()
	{
		return *(SoundScriptManager **)0x0045B4A0;
	}
	void unpause();
	void pause();
	void playEvent(EventType event, void *ent = 0, float param = 0.0f);
};

struct FEManager
{
	char pad[0x15678];
	int fe_done;
};

extern FEManager frontendmanager;

class NamesMenu
{
	char pad0[0x3c];
	int flags;
	char pad1[4];
	FEMenuEntry *first_vis_entry;
	char pad2[0x110];
	FEMenuEntry *secondary_cursor;
	char pad3[0xf0];
	FEMenuEntry *entry[1];

public:
	enum { FEMENU_SCROLLING = 1, num = 15 };
	void SetVis(FEMenuEntry *first);
	void SetSecondaryCursor(FEMenuEntry *entry);
	void OnUp(int c);
};

__asm__(".equ frontendmanager, 0x003F7728");
__asm__(".equ unpause__18SoundScriptManager, 0x0031BFA8");
__asm__(".equ pause__18SoundScriptManager, 0x0031BF98");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");
__asm__(".equ SetVis__9NamesMenuP11FEMenuEntry, 0x0019F6A0");
__asm__(".equ SetSecondaryCursor__9NamesMenuP11FEMenuEntry, 0x001A0818");

void NamesMenu::OnUp(int c)
{
	if(secondary_cursor->up)
	{
		if((flags & FEMENU_SCROLLING) && secondary_cursor == first_vis_entry &&
			first_vis_entry != entry[0])
		{
			FEMenuEntry* first = first_vis_entry->up;

			while(first && first->GetDisable() && first != entry[0])
				first = first->previous;
			if(first->entry_num >= 0)
				SetVis(first);
		}

		FEMenuEntry* tmp = secondary_cursor->up;
		while(tmp && tmp->GetDisable() && tmp->down != entry[0])
			tmp = tmp->up;

		if(tmp && tmp->entry_num < num && tmp->down != entry[0])
		{
			if (frontendmanager.fe_done)
				SoundScriptManager::inst()->unpause();

			SoundScriptManager::inst()->playEvent(SoundScriptManager::SS_FE_UPDOWN);
			if (frontendmanager.fe_done)
				SoundScriptManager::inst()->pause();

			SetSecondaryCursor(tmp);
		}
	}
}
